@Mod.EventBusSubscriber(bus=Mod.EventBusSubscriber.Bus.MOD)
public final class CompatRegistry {
    public static final String TOP = "theoneprobe";
    public static final String PATCHOULI = "patchouli";
    public static final String CLOTH_CONFIG = "cloth_config";
    public static final String CARRY_ON = "carryon";
    public static final String SBACKPACK = "sophisticatedbackpacks";
    public static final String TBACKPACK = "travelersbackpack";
    public static final String CURIOS = "curios";
    public static final String IMMERSIVE_MELODIES = "immersive_melodies";

    @SubscribeEvent
    public static void onEnqueue(InterModEnqueueEvent event) {
        event.enqueueWork(() -> CompatRegistry.checkModLoad(TOP, () -> InterModComms.sendTo((String)TOP, (String)"getTheOneProbe", TheOneProbeInfo::new)));
        event.enqueueWork(() -> CompatRegistry.checkModLoad(PATCHOULI, PatchouliCompat::init));
        event.enqueueWork(() -> CompatRegistry.checkModLoad(CLOTH_CONFIG, () -> {
            if (FMLEnvironment.dist == Dist.CLIENT) {
                MenuIntegration.registerModsPage();
            }
        }));
        event.enqueueWork(() -> {
            if (FMLEnvironment.dist == Dist.CLIENT) {
                ClothConfigScreen.registerNoClothConfigPage();
            }
        });
        event.enqueueWork(() -> CompatRegistry.checkModLoad(CARRY_ON, BlackList::addBlackList));
        event.enqueueWork(() -> CompatRegistry.checkModLoad(CURIOS, CuriosCompat::init));
        event.enqueueWork(() -> CompatRegistry.checkModLoad(SBACKPACK, SBackpackCompat::init));
        event.enqueueWork(() -> CompatRegistry.checkModLoad(TBACKPACK, TBackpackCompat::init));
        event.enqueueWork(() -> CompatRegistry.checkModLoad(IMMERSIVE_MELODIES, ImmersiveMelodiesServerCompat::init));
    }

    private static void checkModLoad(String modId, Runnable runnable) {
        if (ModList.get().isLoaded(modId)) {
            runnable.run();
        }
    }
}

